function stats(){const jobs=projectJobs();return {stopped:jobs.filter(j=>j.state==='stopped').length,all:jobs.length,running:jobs.filter(j=>j.state==='running').length,done:jobs.filter(j=>j.state==='done').length,error:jobs.filter(j=>j.state==='error').length,queued:jobs.filter(j=>j.state==='queued').length,draft:jobs.filter(j=>j.state==='draft').length};}
