function visibleJobs(){const jobs=filteredQueue();queuePage=Math.min(queuePage,Math.max(0,Math.ceil(jobs.length/6)-1));return jobs.slice(queuePage*6,queuePage*6+6);}
function queuePager(){const pages=Math.max(1,Math.ceil(filteredQueue().length/6));return `<nav class="queue-pages" aria-label="Trang tác vụ"><button data-queue-page="-1" ${queuePage===0?'disabled':''}>← Trước</button><span>${Math.min(queuePage+1,pages)} / ${pages}</span><button data-queue-page="1" ${queuePage+1>=pages?'disabled':''}>Sau →</button></nav>`;}
function workerCards(){const workers=state.workers.filter(w=>w.selected&&w.provider!=='local'&&(w.online||state.jobs.some(j=>j.active?.workerId===w.id)));return workers.map(w=>{const j=state.jobs.find(j=>j.active?.workerId===w.id),hold=state.providerHolds?.[w.provider],health=j?'busy':hold?'blocked':!w.online?'offline':w.health||'unchecked';const detail=j?(j.localProgress||j.plan.steps[j.step].name):hold?hold.message:w.reason||(w.ready?'Đã kiểm tra · sẵn sàng':'Chưa kiểm tra ô chat');return `<article class="worker-card ${j?'busy':''}" data-worker="${esc(w.id)}" data-health="${esc(health)}"><div class="worker-top"><span class="provider-logo">${esc(({muse:'M',gemini:'G',chatgpt:'GPT',grok:'G',flow:'V'})[w.provider]||'AI')}</span><b>${esc(w.name)}</b><i class="live-dot"></i></div><p>${esc(j?j.name+' · '+detail:detail)}</p><small>${w.transport==='chrome'?(w.online?'Chrome đã kết nối':'Chrome mất kết nối'):(w.online?'Cửa sổ trong app':'Cửa sổ đã đóng')} · ${w.visibility==='hidden'?'Tab ở nền':w.visibility==='visible'?'Tab đang hiện':'Chưa rõ trạng thái hiển thị'}</small><button data-focus-worker="${esc(w.id)}" type="button">Mở tab</button></article>`;}).join('')||'<p class="muted">Chưa chọn tab AI. Bấm Nhóm tab AI để thiết lập.</p>';}
