function updateComposer(){if(!$('composerHint'))return;const c=state.composer,allowed=c.mode==='images'?M.allowedProviders(state.workflow):Object.keys(MooZBatchComposer.providers);for(const option of $('composerProvider').options)option.disabled=!allowed.includes(option.value);if(!allowed.includes(c.provider)){c.provider=allowed.includes(state.workflow.provider)?state.workflow.provider:allowed[0];c.workerId='';$('composerProvider').value=c.provider;}updateComposerWorker();const ready=state.workers.filter(w=>w.selected&&w.online&&w.ready&&w.provider!=='local'&&!state.providerHolds?.[w.provider]),busy=state.jobs.filter(j=>j.active).length;
 updatePanel($('composerConnectionText'),`${icon('flow')}<span>${ready.length?'<strong>'+ready.length+' tab AI sẵn sàng</strong>':'<strong>Chưa có tab AI sẵn sàng</strong>'} · ${busy} đang xử lý · giới hạn ${state.maxConcurrent} tác vụ trong lô</span>`);
 let count=0,reason='';try{if(c.mode!=='images'){count=MooZBatchComposer.prompts(c.text,c.eachLine).length;if(c.mode==='frames'&&(!asset(c.firstFrame)||!asset(c.lastFrame)))reason='Chọn cả khung đầu và khung cuối trước khi chạy.';if(c.mode==='extend'&&(!asset(c.sourceVideo)||c.provider!=='muse'))reason='Chọn video gốc và AI Muse để nối dài.';if(reason)count=0;}else{const drafts=composerImageTargets();count=drafts.length;reason=count?'':'Thêm ảnh hoặc chọn sản phẩm bản nháp để tiếp tục.';}}catch(e){reason=e.message;}
 $('composerHint').textContent=reason||(c.mode!=='images'?(c.eachLine?'Mỗi dòng là một video riêng. ':'Toàn bộ nội dung tạo một video. ')+count+' yêu cầu · '+(ready.some(w=>w.provider===c.provider)?'sẵn sàng xếp hàng.':'sẽ chờ tab '+MooZBatchComposer.providers[c.provider]+' được chọn và kết nối.') :count+' sản phẩm · '+state.workflow.scenes+' cảnh / sản phẩm · ảnh và yêu cầu được chốt riêng.'+(state.workflow.characterReferenceEnabled?' Có ảnh nhân vật tham chiếu.':''));
 $('composerSubmit').disabled=composerSubmitting||queueStarting||!count||state.jobs.length+(c.mode!=='images'?count:0)>100;$('composerSubmit').querySelector('span').textContent=composerSubmitting?'Đang xếp hàng…':'Tạo video';$('composerGrouping').closest('label').hidden=c.mode==='images';
}
let composerSubmitting=false;
async function submitComposer(){if(composerSubmitting||queueStarting)return;const c=state.composer;composerSubmitting=true;updateComposer();try{
 let targets=[];
 if(c.mode!=='images'){
  if(c.mode==='frames'&&(!asset(c.firstFrame)?.blob||!asset(c.lastFrame)?.blob))throw Error('Chọn cả khung đầu và khung cuối còn trong Kho media.');if(c.mode==='extend'&&(!asset(c.sourceVideo)?.blob||c.provider!=='muse'))throw Error('Chọn video gốc còn trong Kho media và AI Muse.');
  const prompts=MooZBatchComposer.prompts(c.text,c.eachLine);if(state.jobs.length+prompts.length>100)throw Error('Mỗi lô tối đa 100 tác vụ.');
  const plans=prompts.map(prompt=>MooZBatchComposer.textPlan(prompt,c));for(const plan of plans){if(c.mode==='frames')plan.steps[0].prompt='Ảnh 1 là khung đầu, ảnh 2 là khung cuối. Tạo chuyển động liền mạch từ khung đầu đến khung cuối.\n'+plan.steps[0].prompt;if(c.mode==='extend')plan.steps[0].prompt='Tạo đoạn tiếp theo, tiếp nối tự nhiên từ cuối video gốc đính kèm; giữ nhân vật, vật thể, ánh sáng và hướng chuyển động. Trả video mới, không trả lại video gốc.\n'+plan.steps[0].prompt;M.validate(plan,state.workers,{requireTabs:false});}
  for(const [i,prompt]of prompts.entries()){addJob(c.mode==='frames'?[asset(c.firstFrame),asset(c.lastFrame)]:[],prompt.replace(/\s+/g,' ').slice(0,80));const j=state.jobs.at(-1);Object.assign(j,{inputMode:'text',referenceVideoIds:c.mode==='extend'?[c.sourceVideo]:[],note:prompt,draftPlan:plans[i]});targets.push(j.id);}c.text='';
 }else{
  const drafts=composerImageTargets();if(!drafts.length)throw Error('Chọn sản phẩm bản nháp trước.');
  const plan=M.singleTab(state.workflow,c.provider);Object.assign(plan,{ratio:c.ratio,duration:c.duration});M.validate(plan,state.workers,{requireTabs:false});
  for(const j of drafts){if(!j.images.length||j.images.some(id=>!asset(id)?.blob))throw Error(productLabel(j)+': thêm ảnh còn trong kho trước khi chạy.');}
  for(const j of drafts){j.draftPlan=M.copy(plan);if(c.note.trim())j.note=c.note.trim();targets.push(j.id);}
 }
 for(const id of targets)job(id).requestedWorkerId=c.workerId||null;selected.clear();targets.forEach(id=>selected.add(id));saveNow();renderProduction();await startQueue();
 }finally{composerSubmitting=false;updateComposer();}}
function updateHistory(){const pane=$('taskHistory');if(!pane)return;const key=JSON.stringify(state.jobs.filter(j=>['done','error','stopped'].includes(j.state)).map(j=>[j.id,j.state,j.name,j.resultId]));if(pane.dataset.history===key)return;const open=pane.open;pane.outerHTML=historyHTML();$('taskHistory').dataset.history=key;$('taskHistory').open=open;$('taskHistoryRows').onclick=e=>{const b=e.target.closest('[data-history-task]');if(b)chooseJob(b.dataset.historyTask);};}
