function mediaArt(a){if(a.kind==='text')return '<div class="flow-text-art">TXT</div>';return a.kind==='image'?`<img src="${esc(a.url)}" alt="${esc(a.name)}" loading="lazy">`:a.kind==='video'?`<video src="${esc(a.url)}" muted preload="metadata"></video>`:`<div class="audio-art">${Array.from({length:28},(_,i)=>`<i style="height:${12+(i*17%39)}px"></i>`).join('')}</div>`;}
function assetCard(a,pick=false){return `<article class="asset-card" data-asset="${esc(a.id)}"><div class="asset-preview" data-media-play="${esc(a.id)}">${mediaArt(a)}<span class="asset-type">${a.kind==='image'?'ẢNH':a.kind==='audio'?'ÂM THANH':a.kind==='text'?'VĂN BẢN':'VIDEO'}</span></div><div class="asset-info"><strong title="${esc(a.name)}">${esc(a.name)}</strong><small>${a.duration?clock(a.duration)+' · ':''}${a.size?(a.size<1024*1024?Math.max(1,Math.round(a.size/1024))+' KB':(a.size/1024/1024).toFixed(1)+' MB'):'Chưa rõ dung lượng'}</small></div><div class="asset-actions">${pick?`<button data-pick="${esc(a.id)}" class="primary">Chọn tệp này</button>`:`<button data-rename="${esc(a.id)}">Đổi tên</button><button data-delete="${esc(a.id)}" aria-label="Xóa ${esc(a.name)}">${icon('trash')}</button>`}</div></article>`;}
function sourceTabs(selected,attribute){return [['upload','Tệp tải lên'],['result','Kết quả']].map(([key,label])=>`<button type="button" ${attribute}="${key}" aria-pressed="${selected===key}" class="${selected===key?'active':''}">${label} <span>${assets.filter(a=>!a.deleted&&a.origin===key).length}</span></button>`).join('');}
