$('characterReferenceLibrary').onclick=()=>{if(!assets.some(a=>a.kind==='image'&&!a.deleted)){characterStatus('Kho chưa có ảnh. Bấm Tải ảnh nhân vật lên để chọn trên máy.');$('characterReferenceUpload').focus();return;}const draft=characterDraft;openPicker('image',a=>{if(characterDraft!==draft||!$('characterReferenceDialog').open)return;draft.id=a.id;draft.enabled=true;renderCharacterReference();characterStatus('Đã chọn ảnh. Bấm Lưu vào luồng để áp dụng.');},'Chọn ảnh nhân vật tham chiếu');};
$('characterReferenceEnabled').onchange=e=>{characterDraft.enabled=e.target.checked;characterStatus(e.target.checked?'Ảnh nhân vật sẽ đi kèm ảnh sản phẩm ở bước Tạo ảnh và Tạo video.':'Đã tắt sử dụng ảnh nhân vật; ảnh đã chọn vẫn được giữ để bật lại.');};
$('characterReferenceRemove').onclick=()=>{characterDraft.id='';characterDraft.enabled=false;renderCharacterReference();characterStatus('Đã bỏ chọn ảnh nhân vật. Bấm Lưu vào luồng để áp dụng.');};
$('characterReferenceForm').onsubmit=safe(event=>{
 event.preventDefault();if(characterBusy)return;
 const draft=characterDraft,next={...draft.workflow,characterReferenceEnabled:draft.enabled,characterReferenceId:draft.id};
 try{M.validate(next,state.workers,{requireTabs:false});validateCharacterAsset(null,next);next.version=state.workflow.version+1;state.workflow=M.copy(next);workflowDraft=null;saveNow();$('characterReferenceDialog').close();notify('Đã lưu '+(draft.enabled?'ảnh nhân vật tham chiếu':'tắt sử dụng ảnh nhân vật')+'. Tác vụ đã xếp hàng giữ cấu hình trước đó.');renderWorkflow();}catch(error){characterStatus(error.message||String(error),true);}
});

function productStatus(text,error=false){const el=$('productImportStatus');el.textContent=text;el.classList.toggle('error',error);}
function productWorking(busy){productBusy=busy;$('productDrop').disabled=busy;$('productDrop').setAttribute('aria-busy',String(busy));$('productFromLibrary').disabled=busy;document.querySelectorAll('#importGrouping button').forEach(b=>b.disabled=busy);}
async function importProductFiles(files){if(productBusy)return;if(!files.length){productStatus('Chưa chọn ảnh để thêm.');return;}productWorking(true);try{productStatus('Đang thêm '+files.length+' ảnh…');await importFiles(files,true);}catch(error){productStatus(error.message||String(error),true);}finally{productWorking(false);}}
async function chooseProductImages(){if(productBusy)return;productWorking(true);productStatus('Đang mở hộp chọn ảnh trên máy…');try{const result=await call('batch.pickImages');if(result.canceled){productStatus('Chưa chọn ảnh. Bấm chọn ảnh trên máy để thử lại.');return;}if(!result.files.length){productStatus(result.errors.join('\n')||'Chưa có ảnh phù hợp để thêm.',true);return;}productStatus('Đang thêm '+result.files.length+' ảnh…');const files=[];for(const item of result.files){const blob=await(await fetch('data:'+item.mime+';base64,'+item.data)).blob();files.push(new File([blob],item.name,{type:item.mime}));}await importFiles(files,true);if(result.errors.length){productStatus(result.errors.join('\n'),true);notify('Một số ảnh chưa được thêm: '+result.errors.join(' · '),true);}}catch(error){productStatus('Chưa chọn được ảnh: '+(error.message||String(error)),true);}finally{productWorking(false);}}
function wireDrop(element,callback){element.ondragover=e=>{e.preventDefault();element.classList.add('drag-active');};element.ondragleave=()=>element.classList.remove('drag-active');element.ondrop=safe(async e=>{e.preventDefault();element.classList.remove('drag-active');await callback([...e.dataTransfer.files]);});}
async function metadata(url,kind){if(kind==='text')return {};if(kind==='image'){const image=new Image();image.src=url;try{await image.decode();}catch{throw Error('Không đọc được ảnh. Hãy chọn một tệp ảnh hợp lệ.');}return {width:image.naturalWidth,height:image.naturalHeight};}return new Promise((resolve,reject)=>{const el=document.createElement(kind==='video'?'video':'audio'),timer=setTimeout(()=>finish(Error('Không đọc được media trong 15 giây.')),15000);const finish=error=>{clearTimeout(timer);const value={duration:el.duration,width:el.videoWidth,height:el.videoHeight};el.removeAttribute('src');el.load();error?reject(error):resolve(value);};el.preload='metadata';const ready=()=>{if(Number.isFinite(el.duration)&&el.duration>0)finish();};el.ondurationchange=ready;el.ontimeupdate=ready;el.onloadedmetadata=()=>{if(Number.isFinite(el.duration)&&el.duration>0)finish();else if(el.duration===Infinity)el.currentTime=1e100;else finish(Error('Media không có thời lượng hợp lệ.'));};el.onerror=()=>finish(Error('Trình duyệt không đọc được định dạng tệp này.'));el.src=url;});}
async function importFiles(files,asProducts){if(asProducts&&grouping==='together'&&files.length>8)throw Error('Mỗi sản phẩm tối đa 8 ảnh; chọn mỗi ảnh = 1 sản phẩm để tạo nhiều sản phẩm.');if(asProducts&&state.jobs.length+(grouping==='together'?1:files.length)>100)throw Error('Mỗi lô hỗ trợ tối đa 100 sản phẩm.');const added=[],errors=[];for(const file of files){let url;try{const kind=file.type.startsWith('image/')?'image':file.type.startsWith('audio/')?'audio':file.type.startsWith('video/')?'video':/\.(mp3|wav|m4a)$/i.test(file.name)?'audio':/\.(mp4|webm|mov)$/i.test(file.name)?'video':null;if(!kind||file.type==='image/svg+xml'||asProducts&&kind!=='image')throw Error('Định dạng không phù hợp: '+file.name);if(!file.size||file.size>(asProducts?20:100)*1024*1024)throw Error(file.name+': tệp trống hoặc quá lớn.');url=own(file);const a={id:uid(),name:file.name,kind,origin:'upload',createdAt:assetCreatedAt(),mime:file.type||'application/octet-stream',size:file.size,blob:file,url,...await metadata(url,kind)};await storeAsset(a);assets.push(a);added.push(a);}catch(error){if(url){URL.revokeObjectURL(url);urls.delete(url);}const message=error.message.includes(file.name)?error.message:file.name+': '+error.message;errors.push(message);notify(message,true);}}
 if(asProducts&&!added.length)productStatus(errors.join("\n")||"Chưa chọn ảnh để thêm.",!!errors.length);
 if(asProducts&&added.length){state.composer.mode='images';if(grouping==='together')addJob(added,added[0].name.replace(/\.[^.]+$/,''));else for(const a of added)addJob([a],a.name.replace(/\.[^.]+$/,''));$('productDialog').close();setView('production');}else if(view==='library'){librarySource='upload';renderLibrary();}save();$('libraryCount').textContent=assets.filter(a=>!a.deleted).length;if(added.length)notify('Đã thêm '+added.length+' tệp vào kho'+(asProducts?' và tạo sản phẩm.':'.')+(errors.length?' Một số ảnh chưa được thêm: '+errors.join(' · '):''),!!errors.length);return {added,errors};}
function addJob(images,name){if(state.jobs.length>=100)throw Error('Mỗi lô hỗ trợ tối đa 100 sản phẩm.');const ordinal=state.nextSku||Math.max(0,...state.jobs.map(j=>Number(String(j.sku).replace('MZ-',''))||0))+1;state.nextSku=ordinal+1;const j={id:uid(),sku:'MZ-'+String(ordinal).padStart(3,'0'),name,createdAt:new Date().toISOString(),collectionId:state.collectionId,images:images.map(a=>a.id),state:'draft',note:'',step:0,progress:0,logs:[],completed:[]};state.jobs.push(j);selectedJob=j.id;save();}
