$('mainNav').onclick=e=>{const b=e.target.closest('[data-view]');if(b)setView(b.dataset.view);};document.querySelector('.brand').onclick=e=>{e.preventDefault();setView('production');};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());$('poolDialog').addEventListener('close',()=>{save();render();});$('chromeDialog').addEventListener('close',()=>{$('chromeCode').value='';$('chromeCode').type='password';});$('themeToggle').onclick=safe(async()=>{const value=await call('appearance.get');await call('appearance.save',{...value,theme:document.documentElement.dataset.uiTheme==='light'?'dark':'light'});});$('helpOpen').onclick=()=>modal('helpDialog');$('backHome').onclick=()=>void call('home.open');$('refreshTabs').onclick=()=>void refreshTabs();$('quickRefresh').onclick=()=>void refreshTabs();$('openAI').onclick=safe(async()=>{await call('batch.openAI',{provider:$('openProvider').value});notify('Đăng nhập AI, quay lại đây và bấm Cập nhật danh sách tab.');});$('connectChrome').onclick=safe(async()=>{const result=await call('relay.pair');$('chromeCode').value=result.url;modal('chromeDialog');});$('copyChrome').onclick=safe(async()=>{await call('relay.copy');notify('Đã sao chép mã kết nối.');});$('productFiles').onchange=async e=>{await importProductFiles([...e.target.files]);e.target.value='';};$('productDrop').onclick=chooseProductImages;$('libraryFiles').onchange=safe(async e=>{await importFiles([...e.target.files],false);e.target.value='';});$('importGrouping').onclick=e=>{const b=e.target.closest('[data-group]');if(b){grouping=b.dataset.group;document.querySelectorAll('[data-group]').forEach(b=>{const active=b.dataset.group===grouping;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});productStatus(grouping==='together'?'Các ảnh được chọn sẽ gom vào một sản phẩm (tối đa 8 ảnh).':'Mỗi ảnh được chọn sẽ tạo một sản phẩm riêng.');}};wireDrop($('productDrop'),importProductFiles);$('productFromLibrary').onclick=()=>{if(!assets.some(a=>!a.deleted&&a.kind==='image')){productStatus('Kho chưa có ảnh. Bấm chọn ảnh trên máy để thêm ảnh trước.');$('productDrop').focus();return;}openPicker('image',a=>{try{addJob([a],a.name.replace(/\.[^.]+$/,''));$('productDialog').close();setView('production');}catch(error){productStatus(error.message||String(error),true);}},'Chọn ảnh làm sản phẩm mới');};$('renameForm').onsubmit=safe(async e=>{e.preventDefault();const a=asset(renameId),name=$('renameValue').value.trim();if(!a||!name)throw Error('Nhập tên media.');a.name=name;await storeAsset(a);$('renameDialog').close();renderLibrary();notify('Đã đổi tên media.');});
workflowDesktop.onEvent(value=>{if(value.type==='aiDispatch')void refreshDispatch().catch(()=>{});if(value.type==='batch.workerIdle')void refreshTabs(false);if(['relay','created','removed'].includes(value.type))tabsChanged();if(value.type==='batch.progress'){const j=state.jobs.find(j=>j.active?.workerId===value.workerId);if(j)j.localProgress=value.text;}});
document.addEventListener('workflow:appearance',()=>{state.theme=document.documentElement.dataset.uiTheme==='light'?'light':'dark';if(view==='editor')paintWave(waveBuffer);});window.addEventListener('resize',()=>{if(view==='editor'){paintWave(waveBuffer);updateTrims();}else if(view==='production'&&state.compactQueue==null&&document.querySelector('#main .page')?.classList.contains('compact-batch')!==(innerHeight<850))renderProduction();});window.addEventListener('beforeunload',e=>{saveNow();if(exporting){e.preventDefault();e.returnValue='';}});let lastTick=performance.now();setInterval(()=>{const now=performance.now();engine.tick(now-lastTick);lastTick=now;updateProduction();MooZFlowForm.refreshWorkers?.();updateComposerWorker();},120);void init().catch(error=>{notify('Chưa mở được Video hàng loạt: '+error.message,true);console.error(error);});
